const nextInvoiceNumber = `-- name: NextInvoiceNumber :one
INSERT INTO invoice_counters (company_id, kind, year, last_value)
VALUES ($1, $2, $3, 1)
ON CONFLICT (company_id, kind, year) DO UPDATE SET last_value = invoice_counters.last_value + 1
RETURNING last_value
`

type NextInvoiceNumberParams struct {
	CompanyID uuid.UUID
	Kind      string
	Year      int32
}

// Numéro suivant, sans trou (ligne verrouillée jusqu'à la fin de la transaction).
func (q *Queries) NextInvoiceNumber(ctx context.Context, arg NextInvoiceNumberParams) (int32, error) {
	row := q.db.QueryRow(ctx, nextInvoiceNumber, arg.CompanyID, arg.Kind, arg.Year)
	var last_value int32
	err := row.Scan(&last_value)
	return last_value, err
}

const queueInvoiceEmail = `-- name: QueueInvoiceEmail :exec
UPDATE invoices SET email_status = 'pending', email_to = $1, email_attempts = 0, email_next_at = now(), email_error = ''
WHERE id = $2
`

type QueueInvoiceEmailParams struct {
	EmailTo string
	ID      uuid.UUID
}

func (q *Queries) QueueInvoiceEmail(ctx context.Context, arg QueueInvoiceEmailParams) error {
	_, err := q.db.Exec(ctx, queueInvoiceEmail, arg.EmailTo, arg.ID)
	return err
}

const recordInvoiceEmail = `-- name: RecordInvoiceEmail :exec
UPDATE invoices SET
    email_to = $1,
    email_error = $2,
    email_status = $3::text,
    emailed_at = CASE WHEN $3::text <> 'failed' THEN now() ELSE emailed_at END
WHERE id = $4
`

type RecordInvoiceEmailParams struct {
	EmailTo    string
	EmailError string
	Result     string
	ID         uuid.UUID
}

// Envoi manuel ou joint à la confirmation : résultat immédiat, pas de nouvel essai automatique.
func (q *Queries) RecordInvoiceEmail(ctx context.Context, arg RecordInvoiceEmailParams) error {
	_, err := q.db.Exec(ctx, recordInvoiceEmail,
		arg.EmailTo,
		arg.EmailError,
		arg.Result,
		arg.ID,
	)
	return err
}

const setInvoiceEmailResult = `-- name: SetInvoiceEmailResult :exec
UPDATE invoices SET
    email_attempts = email_attempts + 1,
    email_to = $1,
    email_error = $2,
    email_status = CASE
        WHEN $3::text <> 'failed' THEN $3::text
        WHEN email_attempts + 1 >= 5 THEN 'failed'
        ELSE 'pending' END,
    email_next_at = now() + make_interval(mins => 5 * (email_attempts + 1)),
    emailed_at = CASE WHEN $3::text <> 'failed' THEN now() ELSE emailed_at END
WHERE id = $4
`

type SetInvoiceEmailResultParams struct {
	EmailTo    string
	EmailError string
	Result     string
	ID         uuid.UUID
}

// result : sent, simulated ou failed. Échec : nouvel essai 5, 10, 15, 20 min plus tard ; abandon après 5 essais.
func (q *Queries) SetInvoiceEmailResult(ctx context.Context, arg SetInvoiceEmailResultParams) error {
	_, err := q.db.Exec(ctx, setInvoiceEmailResult,
		arg.EmailTo,
		arg.EmailError,
		arg.Result,
		arg.ID,
	)
	return err
}
